<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Illuminate\Validation\Rule; use Pterodactyl\Facades\Activity; use Pterodactyl\Models\Dezerx\RustWipe; use Pterodactyl\Models\Dezerx\RustWipeRun; use Pterodactyl\Services\Dezerx\Rust\RustWipes; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Rust\RustWipesRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Rust\RustWipesManageRequest; class RustWipeController extends ClientApiController { private const HISTORY = 15; public function __construct(private RustWipes $wipes) { parent::__construct(); } public function index(RustWipesRequest $request, Server $server): JsonResponse { $files = new ServerFiles($server); $directory = $this->wipes->directory($server); $entries = $files->listFiles($directory); $buckets = ['map' => ['files' => 0, 'size' => 0], 'blueprints' => ['files' => 0, 'size' => 0], 'players' => ['files' => 0, 'size' => 0]]; foreach ($entries ?? [] as $entry) { if (!$entry['directory'] && ($bucket = $this->wipes->classify($entry['name'])) !== null) { $buckets[$bucket]['files']++; $buckets[$bucket]['size'] += $entry['size']; } } $seed = $this->wipes->variable($server, 'WORLD_SEED'); $size = $this->wipes->variable($server, 'WORLD_SIZE'); $mapUrl = $this->wipes->variable($server, 'MAP_URL'); $runs = RustWipeRun::query()->where('server_id', $server->id)->orderByDesc('id')->limit(self::HISTORY)->get(); $active = $this->wipes->activeRun($server); return new JsonResponse([ 'directory' => $directory, 'readable' => $entries !== null, 'state' => $files->powerStateOrNull(), 'buckets' => $buckets, 'world' => [ 'seed' => $seed?->server_value, 'size' => $size !== null && is_numeric($size->server_value) ? (int) $size->server_value : null, 'seedEditable' => (bool) $seed?->user_editable, 'sizeEditable' => (bool) $size?->user_editable, 'customMap' => trim((string) ($mapUrl?->server_value ?? '')) !== '', ], 'limits' => [ 'warnings' => RustWipes::WARNING_STEPS, 'schedules' => RustWipes::MAX_SCHEDULES, 'extraFiles' => RustWipes::MAX_EXTRA_FILES, 'seeds' => RustWipes::MAX_SEEDS, 'minSize' => RustWipes::MIN_SIZE, 'maxSize' => RustWipes::MAX_SIZE, ], 'defaultMessage' => RustWipes::DEFAULT_MESSAGE, 'wipes' => RustWipe::query()->where('server_id', $server->id)->orderBy('id')->get()->map($this->present(...))->all(), 'active' => $active ? $this->presentRun($active) : null, 'runs' => $runs->map($this->presentRun(...))->all(), ]); } public function store(RustWipesManageRequest $request, Server $server): JsonResponse { if (RustWipe::query()->where('server_id', $server->id)->count() >= RustWipes::MAX_SCHEDULES) { return $this->error('TooMany', 'A server can have ' . RustWipes::MAX_SCHEDULES . ' wipe schedules.', 422); } $wipe = new RustWipe(['server_id' => $server->id, 'created_by' => $request->user()->id]); if ($response = $this->fill($request, $server, $wipe)) { return $response; } Activity::event('server:rust-wipe.create')->property(['name' => $wipe->name])->log(); return new JsonResponse($this->present($wipe), 201); } public function update(RustWipesManageRequest $request, Server $server, int $wipe): JsonResponse { $model = $this->find($server, $wipe); if ($response = $this->fill($request, $server, $model)) { return $response; } if (!$model->enabled) { $this->cancelPending($model); } Activity::event('server:rust-wipe.update')->property(['name' => $model->name])->log(); return new JsonResponse($this->present($model)); } public function destroy(RustWipesManageRequest $request, Server $server, int $wipe): JsonResponse { $model = $this->find($server, $wipe); $this->cancelPending($model); $model->delete(); Activity::event('server:rust-wipe.delete')->property(['name' => $model->name])->log(); return new JsonResponse([], 204); } public function run(RustWipesManageRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'type' => ['required', Rule::in(RustWipes::TYPES)], 'delay' => ['required', 'integer', Rule::in([0, ...RustWipes::WARNING_STEPS])], 'seedMode' => ['required', Rule::in(['keep', 'random'])], ]); if ($data['seedMode'] !== 'keep' && ($response = $this->checkStartup($request, $server, true, false))) { return $response; } if ($this->wipes->activeRun($server) !== null) { return $this->error('AlreadyRunning', 'A wipe is already counting down or running on this server.', 409); } $delay = (int) $data['delay']; $run = RustWipeRun::query()->create([ 'server_id' => $server->id, 'name' => 'Manual wipe', 'trigger' => 'manual', 'status' => RustWipeRun::PENDING, 'settings' => $this->wipes->config([ 'type' => $data['type'], 'warnings' => array_values(array_filter(RustWipes::WARNING_STEPS, fn (int $minutes) => $minutes <= $delay)), 'seedMode' => $data['seedMode'], 'startAfter' => true, ]), 'scheduled_for' => time() + $delay * 60, 'warned' => [], 'user_id' => $request->user()->id, ]); Activity::event('server:rust-wipe.run')->property(['type' => $data['type'], 'delay' => $delay])->log(); return new JsonResponse($this->presentRun($run), 202); } public function cancel(RustWipesManageRequest $request, Server $server, int $run): JsonResponse { $model = RustWipeRun::query()->where('server_id', $server->id)->findOrFail($run); $cancelled = RustWipeRun::query() ->whereKey($model->id) ->where('status', RustWipeRun::PENDING) ->update(['status' => RustWipeRun::CANCELLED, 'error' => 'Cancelled before it started.', 'finished_at' => time(), 'updated_at' => now()]); if ($cancelled === 0) { return $model->refresh()->isActive() ? $this->error('Started', 'This wipe has already started and can no longer be cancelled.', 409) : $this->error('Finished', 'This wipe is already over.', 409); } if ($model->status === RustWipeRun::PENDING && $model->warned) { (new ServerFiles($server))->sendCommand('say "The wipe has been called off."'); } Activity::event('server:rust-wipe.cancel')->property(['name' => $model->name])->log(); return new JsonResponse($this->presentRun($model->refresh())); } private function fill(RustWipesManageRequest $request, Server $server, RustWipe $wipe): ?JsonResponse { $data = $request->validate([ 'name' => ['required', 'string', 'max:64'], 'enabled' => ['required', 'boolean'], 'frequency' => ['required', Rule::in(RustWipes::FREQUENCIES)], 'weekday' => ['nullable', 'integer', 'between:0,6', Rule::requiredIf(fn () => in_array($request->input('frequency'), ['weekly', 'monthly'], true))], 'startsOn' => ['nullable', 'date_format:Y-m-d', Rule::requiredIf(fn () => in_array($request->input('frequency'), ['once', 'biweekly'], true))], 'time' => ['required', 'date_format:H:i'], 'timezone' => ['required', 'string', 'max:64', 'timezone:all_with_bc'], 'type' => ['required', Rule::in(RustWipes::TYPES)], 'warnings' => ['present', 'array', 'max:' . count(RustWipes::WARNING_STEPS)], 'warnings.*' => ['integer', Rule::in(RustWipes::WARNING_STEPS)], 'message' => ['nullable', 'string', 'max:120'], 'seedMode' => ['required', Rule::in(['keep', 'random', 'list'])], 'seeds' => ['present', 'array', 'max:' . RustWipes::MAX_SEEDS], 'seeds.*' => ['string', 'regex:/^\d{1,10}$/'], 'worldSize' => ['nullable', 'integer', 'between:' . RustWipes::MIN_SIZE . ',' . RustWipes::MAX_SIZE], 'extraFiles' => ['present', 'array', 'max:' . RustWipes::MAX_EXTRA_FILES], 'extraFiles.*' => ['string', 'max:200'], 'startAfter' => ['required', 'boolean'], ]); if ($data['seedMode'] === 'list' && $data['seeds'] === []) { return $this->error('NoSeeds', 'Add at least one seed to pick from.', 422); } foreach ($data['seeds'] as $seed) { if ((int) $seed < 1 || (int) $seed > RustWipes::MAX_SEED) { return $this->error('BadSeed', "Seed {$seed} is out of range. Rust takes 1 to " . RustWipes::MAX_SEED . '.', 422); } } foreach ($data['extraFiles'] as $path) { if ($this->wipes->extraPath($path) === null) { return $this->error('BadPath', "\"{$this->wipes->chatText($path, 60)}\" is not a path inside the server. Use a path like oxide/data/Kits.json.", 422); } } $changesSeed = $data['seedMode'] !== 'keep'; $changesSize = $data['worldSize'] !== null; $previous = $wipe->exists ? $this->wipes->config($wipe->config) : null; $sameWorld = $previous !== null && $previous['seedMode'] === $data['seedMode'] && $previous['seeds'] === array_values(array_unique(array_map(fn ($seed) => (string) (int) $seed, $data['seeds']))) && $previous['worldSize'] === ($changesSize ? (int) $data['worldSize'] : null); if (($changesSeed || $changesSize) && !$sameWorld && ($response = $this->checkStartup($request, $server, $changesSeed, $changesSize))) { return $response; } $wipe->forceFill([ 'name' => trim($data['name']), 'enabled' => $data['enabled'], 'frequency' => $data['frequency'], 'weekday' => in_array($data['frequency'], ['weekly', 'monthly'], true) ? (int) $data['weekday'] : null, 'starts_on' => in_array($data['frequency'], ['once', 'biweekly'], true) ? $data['startsOn'] : null, 'at_time' => $data['time'], 'timezone' => $data['timezone'], 'config' => $this->wipes->config($data), ]); $next = $this->wipes->nextOccurrence($wipe, time()); if ($next === null && $data['frequency'] === 'once' && $data['enabled']) { return $this->error('InThePast', 'That date and time has already passed.', 422); } $wipe->next_run_at = $next; $wipe->save(); return null; } private function checkStartup(RustWipesManageRequest $request, Server $server, bool $seed, bool $size): ?JsonResponse { if (!$request->canChangeStartup($server)) { return $this->error('Forbidden', 'Changing the seed or world size needs the startup update permission.', 403); } foreach (array_filter(['WORLD_SEED' => $seed, 'WORLD_SIZE' => $size]) as $name => $_) { $variable = $this->wipes->variable($server, $name); if ($variable === null || !$variable->user_editable) { return $this->error('NotEditable', "This server's egg does not let {$name} be changed.", 422); } } return null; } private function find(Server $server, int $id): RustWipe { return RustWipe::query()->where('server_id', $server->id)->findOrFail($id); } private function cancelPending(RustWipe $wipe): void { RustWipeRun::query() ->where('wipe_id', $wipe->id) ->where('status', RustWipeRun::PENDING) ->update(['status' => RustWipeRun::CANCELLED, 'error' => 'The schedule was turned off or deleted.', 'finished_at' => time(), 'updated_at' => now()]); } private function present(RustWipe $wipe): array { return [ 'id' => $wipe->id, 'name' => $wipe->name, 'enabled' => $wipe->enabled, 'frequency' => $wipe->frequency, 'weekday' => $wipe->weekday, 'startsOn' => $wipe->starts_on, 'time' => $wipe->at_time, 'timezone' => $wipe->timezone, 'nextRunAt' => $wipe->next_run_at, 'lastRunAt' => $wipe->last_run_at, ] + $this->wipes->config($wipe->config); } private function presentRun(RustWipeRun $run): array { return [ 'id' => $run->id, 'wipeId' => $run->wipe_id, 'name' => $run->name, 'trigger' => $run->trigger, 'status' => $run->status, 'type' => $run->settings['type'] ?? 'map', 'warnings' => $run->settings['warnings'] ?? [], 'warned' => $run->warned ?? [], 'scheduledFor' => $run->scheduled_for, 'startedAt' => $run->started_at, 'finishedAt' => $run->finished_at, 'seed' => $run->seed, 'deleted' => $run->deleted ?? [], 'error' => $run->error, ]; } private function error(string $code, string $detail, int $status): JsonResponse { return new JsonResponse(['errors' => [['code' => $code, 'status' => (string) $status, 'detail' => $detail]]], $status); } } 